# Compute durations in minutes for each incomplete inbox task
tasks_with_dur = []
for t in incomplete_inbox:
    dur = t['duration']
    unit = t['duration_unit']
    if unit == 'minutes':
        dur_min = dur
    elif unit == 'hours':
        dur_min = dur * 60
    elif unit == 'days':
        dur_min = dur * 1440
    else:
        dur_min = dur  # fallback
    tasks_with_dur.append((t['task_id'], t['title'], dur_min, t))

# Sort by duration ascending to maximize count
tasks_with_dur.sort(key=lambda x: x[2])
print("Sorted by duration (minutes):")
for tid, title, d, _ in tasks_with_dur:
    print(f"{tid}: {title} - {d} min")

